'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var strided = require( '@stdlib/blas/base/dspr' ).ndarray;


// MAIN //

/**
* Performs the symmetric rank 1 operation `A = alpha*x*x^T + A`, where `alpha` is a scalar, `x` is an ndarray, and `A` is an `N` by `N` symmetric matrix supplied in packed form.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional symmetric input ndarray.
*     -   first zero-dimensional ndarray containing a scalar constant.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var A = new ndarray( 'float64', new Float64Array( [ 1.0, 2.0, 3.0, 1.0, 2.0, 1.0 ] ), [ 6 ], [ 1 ], 0, 'row-major' );
*
* var alpha = scalar2ndarray( 1.0, {
*     'dtype': 'float64'
* });
*
* var out = dspr( [ x, A, alpha ] );
* // returns <ndarray>[ 2.0, 4.0, 6.0, 5.0, 8.0, 10.0 ]
*
* var bool = ( out === A );
* // returns true
*/
function dspr( arrays ) {
	var alpha = ndarraylike2scalar( arrays[ 2 ] );
	var x = arrays[ 0 ];
	var A = arrays[ 1 ];
	strided( 'row-major', 'upper', numelDimension( x, 0 ), alpha, getData( x ), getStride( x, 0 ), getOffset( x ), getData( A ), getStride( A, 0 ), getOffset( A ) );
	return A;
}


// EXPORTS //

module.exports = dspr;
